DROP TABLE IF EXISTS merchants, payments, chargebacks CASCADE;
CREATE TABLE merchants (id int PRIMARY KEY, city text, country text, currency text);
INSERT INTO merchants
  SELECT g, (ARRAY['Amsterdam','London','Zurich','Stockholm','Oslo','Copenhagen','Warsaw','Prague','Budapest','Tokyo'])[1 + g % 10],
            (ARRAY['NL','GB','CH','SE','NO','DK','PL','CZ','HU','JP'])[1 + g % 10],
            (ARRAY['EUR','GBP','CHF','SEK','NOK','DKK','PLN','CZK','HUF','JPY'])[1 + g % 10]
  FROM generate_series(1, 10000) g;
CREATE TABLE payments (id bigint PRIMARY KEY, merchant_id int, amount_cents bigint);
INSERT INTO payments
  SELECT g, 1 + (g * 7919) % 10000, (100000 * power(((g * 104729) % 100000) / 100000.0, 3))::bigint
  FROM generate_series(1, 1000000::bigint) g;
CREATE INDEX ON payments (merchant_id);
CREATE TABLE chargebacks (id int PRIMARY KEY, payment_id bigint);
INSERT INTO chargebacks SELECT g, 1 + (g * 49999) % 1000000 FROM generate_series(1, 20000) g;
VACUUM ANALYZE merchants, payments, chargebacks;

SELECT relpages, reltuples FROM pg_class WHERE relname = 'payments';
EXPLAIN SELECT * FROM payments;
EXPLAIN SELECT * FROM payments WHERE amount_cents > 50000;

ANALYZE VERBOSE payments;
SELECT min(amount_cents), max(amount_cents) FROM payments;
SELECT n_distinct, (histogram_bounds::text::bigint[])[1:6] AS first_bounds,
       (histogram_bounds::text::bigint[])[96:101] AS last_bounds
FROM pg_stats WHERE tablename = 'payments' AND attname = 'amount_cents';
EXPLAIN (ANALYZE, TIMING OFF, BUFFERS OFF, SUMMARY OFF)
  SELECT * FROM payments WHERE amount_cents < 1000;
SELECT n_distinct, most_common_vals, most_common_freqs
FROM pg_stats WHERE tablename = 'merchants' AND attname = 'city';
EXPLAIN (ANALYZE, TIMING OFF, BUFFERS OFF, SUMMARY OFF)
  SELECT * FROM merchants WHERE city = 'Amsterdam';

EXPLAIN (ANALYZE, TIMING OFF, BUFFERS OFF, SUMMARY OFF)
  SELECT * FROM merchants WHERE city = 'Amsterdam' AND country = 'NL';
EXPLAIN (ANALYZE, TIMING OFF, BUFFERS OFF, SUMMARY OFF)
  SELECT * FROM merchants WHERE city = 'Amsterdam' AND country = 'NL' AND currency = 'EUR';
CREATE STATISTICS merchants_geo (dependencies) ON city, country, currency FROM merchants;
ANALYZE merchants;
SELECT dependencies FROM pg_stats_ext WHERE statistics_name = 'merchants_geo';
EXPLAIN (ANALYZE, TIMING OFF, BUFFERS OFF, SUMMARY OFF)
  SELECT * FROM merchants WHERE city = 'Amsterdam' AND country = 'NL' AND currency = 'EUR';

DROP STATISTICS IF EXISTS merchants_geo;
ANALYZE merchants;
SET max_parallel_workers_per_gather = 0;
EXPLAIN (ANALYZE, TIMING OFF, BUFFERS)
  SELECT count(*) FROM merchants m
  JOIN payments p ON p.merchant_id = m.id
  JOIN chargebacks c ON c.payment_id = p.id
  WHERE m.city = 'Amsterdam' AND m.country = 'NL' AND m.currency = 'EUR';
CREATE STATISTICS merchants_geo (dependencies) ON city, country, currency FROM merchants;
ANALYZE merchants;
EXPLAIN (ANALYZE, TIMING OFF, BUFFERS)
  SELECT count(*) FROM merchants m
  JOIN payments p ON p.merchant_id = m.id
  JOIN chargebacks c ON c.payment_id = p.id
  WHERE m.city = 'Amsterdam' AND m.country = 'NL' AND m.currency = 'EUR';
RESET ALL;

