fun bestPlan(graph: JoinGraph, rows: (Int) -> Double = graph::estimate): Plan {
    val best = arrayOfNulls<Plan>(graph.all + 1)
    for (t in 0 until graph.size) best[1 shl t] = Leaf(t, rows(1 shl t))
    for (set in 1..graph.all) {                    // subsets are smaller numbers: done first
        if (Integer.bitCount(set) < 2) continue
        val out = rows(set)
        var left = (set - 1) and set
        while (left > 0) {
            val right = set xor left
            val l = best[left]
            val r = best[right]
            if (l != null && r != null && graph.connects(left, right)) {
                val candidate = Join(l, r, out)
                if (best[set] == null || candidate.cost < best[set]!!.cost) best[set] = candidate
            }
            left = (left - 1) and set
        }
    }
    return best[graph.all] ?: throw IllegalArgumentException("join graph not connected")
}

// 10 tables: 2^10 - 1 = 1,023 non-empty sets, against 3,628,800 left-deep orders.
